namespace AnoWowItemEditor;

internal sealed record SetEquipPreview(CharacterSnapshot Before,CharacterSnapshot After,Dictionary<int,CatalogItem> Slots,List<string> Problems,List<string> Notes)
{
    internal bool Allowed=>Problems.Count==0;
}
internal sealed record SetPieceBalance(string Item,string Slot,int Level,string Rarity,long Allocation,int Peers,string Assessment);
internal sealed record SetBalanceReport(List<DesignMetric> Metrics,List<SetPieceBalance> Pieces,List<string> Findings,List<string> Bonuses,int CommonSlots);
internal static class SetDesignReview
{
    internal static SetEquipPreview Equip(CharacterSnapshot original,IEnumerable<CatalogItem> pieces,IReadOnlyDictionary<int,CatalogItem> lookup,int level,IReadOnlyDictionary<int,int>? preferred=null)
    {
        var items=pieces.ToArray();var slots=new Dictionary<int,CatalogItem>();var problems=new List<string>();var notes=new List<string>();
        foreach(var item in items.OrderByDescending(i=>i.Slot==17).ThenBy(i=>GearDesign.Targets(i).Length)){
            var targets=GearDesign.Targets(item);if(preferred?.TryGetValue(item.Id,out int chosen)==true){if(!targets.Contains(chosen)){problems.Add($"{item.Name}: requested slot is incompatible.");continue;}targets=[chosen];}
            int? target=targets.Where(s=>!slots.ContainsKey(s)&&!(s==16&&slots.GetValueOrDefault(15)?.Slot==17)).Select(s=>(int?)s).FirstOrDefault();if(!target.HasValue){problems.Add($"{item.Name}: no free compatible slot; conflicting piece excluded from hypothetical totals.");continue;}slots[target.Value]=item;
            int mask=item.Number("AllowableClass");if(mask>0&&(mask&(1<<(original.Character.ClassId-1)))==0)problems.Add($"{item.Name}: this character's class is excluded.");if(item.RequiredLevel>level)problems.Add($"{item.Name}: requires level {item.RequiredLevel}; preview is {level}.");int skill=item.Number("RequiredSkill");if(skill>0&&(original.Skills?.GetValueOrDefault(skill)??0)<item.Number("RequiredSkillRank"))problems.Add($"{item.Name}: saved required skill/rank is not met.");if(item.Number("ItemLimitCategory")!=0)notes.Add($"{item.Name}: category equip restrictions require in-game verification.");
        }
        var replaced=slots.Keys.ToHashSet();if(slots.GetValueOrDefault(15)?.Slot==17)replaced.Add(16);if(slots.ContainsKey(16)&&!slots.ContainsKey(15)&&original.Items.Any(i=>i.Equipped&&i.Slot==15&&lookup.GetValueOrDefault(i.Entry)?.Slot==17)){replaced.Add(15);notes.Add("The existing two-handed main hand is cleared to equip the selected off-hand.");}
        var retained=original.Items.Where(i=>!i.Equipped||!replaced.Contains(i.Slot)).ToList();ulong guid=ulong.MaxValue;foreach(var (slot,item) in slots)retained.Add(new(guid--,item.Id,1,0,slot,"Set preview",0,"","",0,0,true));var after=original with{Character=original.Character with{Level=level},Items=retained};
        foreach(var group in after.Items.Where(i=>i.Equipped).GroupBy(i=>i.Entry).Where(g=>g.Count()>1))if(lookup.GetValueOrDefault(group.Key)?.Number("MaxCount")==1)problems.Add($"{lookup[group.Key].Name}: a unique copy remains equipped in another slot.");
        if(slots.TryGetValue(16,out var off)&&off.ClassId==2)notes.Add("Off-hand weapon proficiency and dual-wield talents require in-game verification.");notes.Add("Simulation only: no character or item data is changed. Values compare gear base stats, not the complete character sheet.");notes.Add("Enchant/gem contributions, talents, buffs, proc damage, set-effect stat totals and rating-to-percentage conversions are excluded. Conditional set bonuses and class proficiencies require in-game verification.");notes.Add("Fixed-level items remain fixed. Only supported server scaling rules change calculated values when preview level changes.");return new(original,after,slots,problems,notes.Distinct().ToList());
    }
    internal static SetBalanceReport Balance(CatalogResult catalog,ItemSetInfo designed,ItemSetInfo reference,IEnumerable<CatalogItem> selected,int level,bool commonOnly=true)
    {
        var lookup=catalog.Items.ToDictionary(i=>i.Id);var pieces=selected.ToArray();var empty=new CharacterSnapshot(new(0,"Set balance",level,1,false,0),[]);var left=Equip(empty,reference.Members.Where(lookup.ContainsKey).Select(id=>lookup[id]),lookup,level);var right=Equip(empty,pieces,lookup,level);var common=left.Slots.Keys.Intersect(right.Slots.Keys).ToHashSet();var findings=new List<string>();
        if(common.Count==0)findings.Add("No common equipment slots: a numeric set comparison is unavailable.");if(commonOnly)findings.Add($"Base-stat comparison uses {common.Count} common equipment slots. Unmatched pieces are excluded from this numeric comparison; bonuses below use complete selected sets.");else findings.Add("Base-stat comparison includes all selected slots. Different piece counts can dominate the totals.");
        string Missing(Dictionary<int,CatalogItem> a,Dictionary<int,CatalogItem> b)=>string.Join(", ",a.Keys.Except(b.Keys).Select(s=>GearDesign.EquipmentSlots[s]));var referenceOnly=Missing(left.Slots,right.Slots);var designedOnly=Missing(right.Slots,left.Slots);if(referenceOnly.Length>0)findings.Add("Reference-only slots: "+referenceOnly);if(designedOnly.Length>0)findings.Add("Designed-set-only slots: "+designedOnly);
        var before=left.After with{Items=left.After.Items.Where(i=>!commonOnly||common.Contains(i.Slot)).ToList()};var after=right.After with{Items=right.After.Items.Where(i=>!commonOnly||common.Contains(i.Slot)).ToList()};var metrics=GearDesign.Compare(before,after,lookup,catalog.Tooltips,level);
        var rows=new List<SetPieceBalance>();foreach(var item in pieces){var budget=GearDesign.Budget(item,catalog.Items,catalog.Tooltips,level);rows.Add(new(item.Name,item.SlotName,item.ItemLevel,CatalogItem.Qualities.ElementAtOrDefault(item.Quality)??"Unknown",budget.Allocation,budget.Peers.Count,budget.Assessment));if(budget.Peers.Count==0||budget.Assessment.Contains("unusually",StringComparison.OrdinalIgnoreCase))findings.Add(item.Name+": "+budget.Assessment);var calculated=catalog.Tooltips.Calculations.Evaluate(item,level);if(calculated.Note.StartsWith("MISSING")||calculated.ItemLevel is null)findings.Add(item.Name+": "+calculated.Note);}
        findings.AddRange(right.Problems.Where(p=>p.Contains("no free")));int classes=-1;foreach(var item in pieces)if(item.Number("AllowableClass")>0)classes&=item.Number("AllowableClass");if(classes==0)findings.Add("No allowed class is shared by all selected pieces.");if(pieces.Length>0&&pieces.Max(i=>i.ItemLevel)-pieces.Min(i=>i.ItemLevel)>10)findings.Add("Item levels differ by more than 10 within this set; review the level spread.");if(pieces.Where(i=>i.ClassId==4&&i.Number("SubclassID") is >=1 and <=4).Select(i=>i.Number("SubclassID")).Distinct().Count()>1)findings.Add("Mixed armor materials: verify the intended class can equip every piece.");
        foreach(var duplicate in designed.Bonuses.GroupBy(b=>(b.SpellId,b.Specialization,b.Trait)).Where(g=>g.Count()>1))findings.Add("Repeated bonus spell: "+catalog.Tooltips.SpellName(duplicate.Key.SpellId));foreach(var bonus in designed.Bonuses.Where(b=>b.Pieces>pieces.Select(i=>i.Id).Distinct().Count()))findings.Add($"The {bonus.Pieces}-piece bonus cannot activate with the selected pieces.");
        var bonuses=new List<string>();void AddBonuses(string label,ItemSetInfo set,int count){bonuses.Add(label+": "+set.Name+$" · {count} pieces");foreach(var b in set.Bonuses.OrderBy(b=>b.Pieces)){bool conditional=b.Specialization!=0||b.Trait!=0||set.Flags!=0||set.RequiredSkill!=0;bonuses.Add($"({b.Pieces}) {(count>=b.Pieces?conditional?"Conditional":"Threshold met":"Inactive")}: {catalog.Tooltips.SpellDescription(b.SpellId)}"+(conditional?" [specialization/skill/trait conditions apply]":""));}}AddBonuses("REFERENCE",reference,reference.Members.Count(lookup.ContainsKey));AddBonuses("DESIGNED SET",designed,pieces.Select(i=>i.Id).Distinct().Count());findings.Add("Peer allocation outliers are design guides, not a universal power score. Proc and set-bonus power is listed separately and is not included in base-stat totals.");return new(metrics,rows,findings,bonuses,common.Count);
    }
}
